module decipher(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [255:0] string_in,\n    input wire [511:0] dict_words,\n    input wire [31:0] dict_lengths,\n    output reg done,\n    output reg [1:0] result_status,\n    output reg [255:0] result_sentence\n);\n\n    // States for the main FSM\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] PRECOMPUTE = 3'b001;\n    localparam [2:0] SEARCH = 3'b010;\n    localparam [2:0] RESULT = 3'b011;\n\n    reg [2:0] state, next_state;\n\n    // Word signature storage\n    reg [3:0] word_length [0:7];\n    reg [7:0] first_char [0:7];\n    reg [7:0] last_char [0:7];\n    reg [127:0] internal_multiset [0:7];\n\n    // Search variables\n    reg [4:0] string_pos;\n    reg [2:0] word_idx;\n    reg [2:0] match_count;\n    reg [2:0] segmentation_count;\n    reg [255:0] stored_sentence;\n    reg [2:0] stored_word_count;\n\n    // Helper: compute multiset of internal letters\n    function [127:0] compute_multiset(input [3:0] length, input [63:0] word);\n        integer i;\n        reg [7:0] char;\n        begin\n            compute_multiset = 128'b0;\n            for (i = 1; i < length-1; i = i + 1) begin\n                char = word[8*i +: 8];\n                if (char >= 8'h61 && char <= 8'h7a) begin\n                    compute_multiset[char*5 +: 5] = compute_multiset[char*5 +: 5] + 1;\n                end\n            end\n        end\n    endfunction\n\n    // Helper: check if substring matches word\n    function matches(input [4:0] str_pos, input [2:0] w_idx);\n        reg [3:0] len;\n        reg [7:0] s_first, s_last;\n        reg [63:0] substring;\n        reg [127:0] sub_multiset;\n        begin\n            len = word_length[w_idx];\n            if (str_pos + len > 32) begin\n                matches = 0;\n            end else begin\n                s_first = string_in[8*str_pos +: 8];\n                s_last = string_in[8*(str_pos+len-1) +: 8];\n                substring = string_in[8*str_pos +: 8*len];\n                if (len == 0 || s_first != first_char[w_idx] || s_last != last_char[w_idx]) begin\n                    matches = 0;\n                end else if (len <= 2) begin\n                    matches = 1;\n                end else begin\n                    sub_multiset = compute_multiset(len, substring);\n                    matches = (sub_multiset == internal_multiset[w_idx]);\n                end\n            end\n        end\n    endfunction\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result_status <= 2'b00;\n            result_sentence <= 256'b0;\n            string_pos <= 5'b0;\n            word_idx <= 3'b0;\n            match_count <= 3'b0;\n            segmentation_count <= 3'b0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                end\n                PRECOMPUTE: begin\n                    if (word_idx < 8) begin\n                        word_length[word_idx] = dict_lengths[word_idx*4 +: 4];\n                        first_char[word_idx] = dict_words[word_idx*64 +: 8];\n                        last_char[word_idx] = dict_words[word_idx*64 + 8*(dict_lengths[word_idx*4 +: 4]-1) +: 8];\n                        internal_multiset[word_idx] = compute_multiset(dict_lengths[word_idx*4 +: 4], dict_words[word_idx*64 +: 64]);\n                        word_idx <= word_idx + 1;\n                    end\n                end\n                SEARCH: begin\n                    if (string_pos < 32 && word_idx < 8) begin\n                        if (matches(string_pos, word_idx)) begin\n                            if (string_pos + word_length[word_idx] == 32) begin\n                                segmentation_count <= segmentation_count + 1;\n                                if (segmentation_count == 1) begin\n                                    stored_sentence <= result_sentence;\n                                    stored_word_count <= match_count + 1;\n                                end\n                            end\n                        end\n                        word_idx <= word_idx + 1;\n                    end else if (string_pos < 32 && word_idx == 8) begin\n                        string_pos <= string_pos + 1;\n                        word_idx <= 3'b0;\n                    end\n                end\n                RESULT: begin\n                    done <= 1'b1;\n                    if (segmentation_count == 0) begin\n                        result_status <= 2'b01;\n                        result_sentence <= "impossible";\n                    end else if (segmentation_count == 1) begin\n                        result_status <= 2'b00;\n                        result_sentence <= "valid";\n                    end else begin\n                        result_status <= 2'b10;\n                        result_sentence <= "ambiguous";\n                    end\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = PRECOMPUTE;\n            PRECOMPUTE: if (word_idx == 8) next_state = SEARCH;\n            SEARCH: if (string_pos >= 32) next_state = RESULT;\n            RESULT: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule